"""Regenerate docs/role-permission-matrix.md from backend/permissions.py (the enforced source of truth)."""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from backend.permissions import DEFAULT_ROLES, PERMISSIONS  # noqa: E402

roles = list(DEFAULT_ROLES)
lines = ["# Default role / permission matrix", "",
         "Generated by `python scripts/gen_permission_matrix.py` from `backend/permissions.py`. "
         "These are the **defaults** seeded for a new database; the CEO can change them under Settings > Roles and permissions "
         "(every change is audited). Permissions are enforced by the backend on every request.", "",
         "| Scope | " + " | ".join(DEFAULT_ROLES[r]["name"] for r in roles) + " |",
         "|---|" + "---|" * len(roles),
         "| Locations | " + " | ".join("All" if DEFAULT_ROLES[r]["scope_all_locations"] else "Assigned only" for r in roles) + " |",
         "", "| Permission | Description | " + " | ".join(DEFAULT_ROLES[r]["name"] for r in roles) + " |",
         "|---|---|" + ":-:|" * len(roles)]
group = None
for code, desc in PERMISSIONS.items():
    g = code.split(".")[0]
    if g != group:
        lines.append(f"| **{g}** | | " + " | " * (len(roles) - 1) + " |")
        group = g
    cells = ["x" if code in DEFAULT_ROLES[r]["permissions"] else "" for r in roles]
    lines.append(f"| `{code}` | {desc} | " + " | ".join(cells) + " |")
Path(__file__).resolve().parents[1].joinpath("docs/role-permission-matrix.md").write_text("\n".join(lines) + "\n")
print("written", len(PERMISSIONS), "permissions")
